package mcp

// The tools/list entries of the ITSA tools, as src/mcp.ts's JSON.stringify writes them (generated by testdata/genlistings.mjs; mcp_test.go compares).
var itsaListings = map[string]string{
	"itsa_create": "{\"name\":\"itsa_create\",\"group\":\"itsas\",\"description\":\"Create an ITSA: a nestable, tracked piece of work (initiative, project, milestone, or issue are only a kind label; any ITSA can hold children). You join as a participant only when you are its owner. Returns its readable key like S-42. ITSAs are optional.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"title\":{\"type\":\"string\",\"description\":\"Required. 1-4 words, a noun phrase that names the thing, like `Phone mail header`: no sentence, no colon, no parent key. The one-line detail goes in summary.\"},\"summary\":{\"type\":\"string\",\"description\":\"One-line description.\"},\"body\":{\"type\":\"string\",\"description\":\"Markdown body.\"},\"parent\":{\"type\":\"string\",\"description\":\"Parent ITSA by id or key. Omit for a root.\"},\"kind\":{\"type\":\"string\",\"description\":\"A label: initiative, project, milestone, issue, or proposal. An ITSA answering retro items (an Answers: line under Retros, or a retro steward's) with an instruction or template edit (a diff touching blocks/, templates/, CLAUDE.md, AGENTS.md, or registry/) must be proposal; a code fix answering retro items may be an issue.\"},\"status\":{\"type\":\"string\",\"description\":\"A status name; defaults to backlog.\"},\"owner\":{\"type\":\"string\",\"description\":\"An agent id or name, or \\\"human\\\". Defaults to nobody.\"},\"participants\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Agents or \\\"human\\\" to keep informed; the owner is always one.\"},\"links\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"url\":{\"type\":\"string\"},\"system\":{\"type\":\"string\"},\"external_id\":{\"type\":\"string\"}},\"required\":[\"url\"]},\"description\":\"Links to external items (a PR, an issue, a URL).\"}},\"required\":[\"title\"]}}",
	"itsa_get":    "{\"name\":\"itsa_get\",\"group\":\"itsas\",\"description\":\"One ITSA by id or key: title, status, owner, summary, parent chain, participants, links, and its direct children with each one's roll-up.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"ref\":{\"type\":\"string\",\"description\":\"ITSA id or key, like S-42.\"}},\"required\":[\"ref\"]}}",
	"itsa_list":   "{\"name\":\"itsa_list\",\"group\":\"itsas\",\"description\":\"List ITSAs as short rows (key, status, owner, title). Filters: mine (you own or take part in), parent, subtree, status, category, owner, participant, kind, text. Use mine to see your own work.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"mine\":{\"type\":\"boolean\",\"description\":\"Only ITSAs you own or take part in.\"},\"parent\":{\"type\":\"string\",\"description\":\"Direct children of this ITSA; \\\"root\\\" for top-level ITSAs.\"},\"subtree\":{\"type\":\"string\",\"description\":\"This ITSA and everything below it.\"},\"status\":{\"type\":\"string\"},\"category\":{\"type\":\"string\",\"description\":\"backlog, ready, active, review, or closed.\"},\"owner\":{\"type\":\"string\"},\"participant\":{\"type\":\"string\"},\"kind\":{\"type\":\"string\"},\"text\":{\"type\":\"string\",\"description\":\"Match against title, summary, or body.\"}}}}",
	"itsa_set":    "{\"name\":\"itsa_set\",\"group\":\"itsas\",\"description\":\"Change an ITSA: status, owner, title, summary, body, kind, parent, participants, or Work page column values (fields). Use a closed status to finish it. Use a human status only for a question only your user can answer (post a comment with itsa_post first: a human status is refused until you have); for anything your parent or the chief of staff can decide, use waiting or blocked. Moving an ITSA out of a human status withdraws the ask from your user. Returns what changed.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"ref\":{\"type\":\"string\",\"description\":\"ITSA id or key.\"},\"title\":{\"type\":\"string\",\"description\":\"1-4 words, a noun phrase that names the thing, like `Phone mail header`: no sentence, no colon, no parent key. The one-line detail goes in summary.\"},\"summary\":{\"type\":\"string\"},\"body\":{\"type\":\"string\"},\"kind\":{\"type\":\"string\"},\"status\":{\"type\":\"string\",\"description\":\"A status name. A closed one finishes the ITSA.\"},\"owner\":{\"type\":\"string\",\"description\":\"An agent id or name, or \\\"human\\\".\"},\"parent\":{\"type\":\"string\",\"description\":\"Move it under this ITSA, or \\\"root\\\" to free it.\"},\"participants\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Replace the participant list (the owner stays one).\"},\"fields\":{\"type\":\"object\",\"description\":\"Values for Work page columns, by field key (see itsa_fields list); null clears one. For example {\\\"stage\\\": \\\"dev\\\"}.\"},\"incident\":{\"type\":\"boolean\",\"description\":\"Mark the ITSA an incident (true) or clear the mark (false). Only the chief of staff or your user may set it; a developer spawn with urgent incident then goes ahead under it or its child ITSAs. Closing the ITSA clears the mark.\"}},\"required\":[\"ref\"]}}",
	"itsa_fields": "{\"name\":\"itsa_fields\",\"group\":\"itsas\",\"description\":\"The Work page columns, called ITSA fields: a field is a shared column that agents fill per ITSA (with itsa_set fields), and its description says what goes in it. action: list (default), create, update, remove, or order. create needs key (a slug), label, and type (text, number, choice, link, date, check); a choice field needs options. update and remove take field (key or id). order takes order: field keys, first to last. Your user may always change fields; while a chief of staff is set, only that agent may, and others get a refusal naming it: mail them to ask. With none set, any agent may, sparingly.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"action\":{\"type\":\"string\",\"enum\":[\"list\",\"create\",\"update\",\"remove\",\"order\"]},\"field\":{\"type\":\"string\",\"description\":\"update and remove: the field key or id.\"},\"key\":{\"type\":\"string\",\"description\":\"A slug: lowercase letters, digits, - and _.\"},\"label\":{\"type\":\"string\"},\"type\":{\"type\":\"string\",\"enum\":[\"text\",\"number\",\"choice\",\"link\",\"date\",\"check\"]},\"options\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"value\":{\"type\":\"string\"},\"label\":{\"type\":\"string\"},\"tone\":{\"type\":\"string\",\"enum\":[\"ok\",\"warn\",\"bad\",\"muted\",\"accent\"]}},\"required\":[\"value\"]},\"description\":\"A choice field's options.\"},\"description\":{\"type\":\"string\",\"description\":\"What goes in this column, for the agents that fill it.\"},\"hint\":{\"type\":\"string\"},\"width\":{\"type\":\"string\",\"enum\":[\"s\",\"m\",\"l\"]},\"align\":{\"type\":\"string\",\"enum\":[\"start\",\"end\"]},\"card\":{\"type\":\"string\",\"enum\":[\"chip\",\"meta\"]},\"kinds\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"The ITSA kinds this field applies to, such as [\\\"issue\\\"]: other ITSAs skip it, and a value on one is refused. Omit or [] for every kind. Narrowing keeps values and hides them.\"},\"order\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"order: field keys, first to last.\"}}}}",
	"itsa_link":   "{\"name\":\"itsa_link\",\"group\":\"itsas\",\"description\":\"Link an ITSA to something outside it, or record on one of its links. To add a link, give ref and a url (and system, or external_id). To link a branch for the merge queue, give ref, system \\\"branch\\\", external_id (the branch name), and repo (a name in settings.itsa.repos). To record on a branch link, give ref and n (its number), with any of: review ({verdict: approve, request_changes, or comment; summary}), tests ({passed, failed, skipped, command}), screenshots ([{mail_id, name}] naming attachments on mail, such as ones in the ITSA's thread). Each field given replaces that part of the record.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"ref\":{\"type\":\"string\",\"description\":\"ITSA id or key.\"},\"url\":{\"type\":\"string\",\"description\":\"A link's url. Optional for a branch link.\"},\"system\":{\"type\":\"string\",\"description\":\"The link kind: github, url, or branch.\"},\"external_id\":{\"type\":\"string\",\"description\":\"An outside id, such as a PR number, or a branch name for a branch link.\"},\"repo\":{\"type\":\"string\",\"description\":\"A branch link's repo: a name in settings.itsa.repos.\"},\"n\":{\"type\":\"number\",\"description\":\"The link number to record on (a branch link).\"},\"review\":{\"type\":\"object\",\"description\":\"{ verdict: approve | request_changes | comment, summary }.\"},\"tests\":{\"type\":\"object\",\"description\":\"{ passed, failed, skipped, command }: counts of whole numbers.\"},\"screenshots\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"mail_id\":{\"type\":\"string\"},\"name\":{\"type\":\"string\"}},\"required\":[\"mail_id\",\"name\"]},\"description\":\"Attachments on mail that show the change.\"}},\"required\":[\"ref\"]}}",
	"itsa_post":   "{\"name\":\"itsa_post\",\"group\":\"itsas\",\"description\":\"Comment on an ITSA, or post a status update, in the ITSA's mail thread (the first post creates the thread). It goes to the ITSA's participants except you, plus anyone in `to`, and makes you a participant. Your user gets it only when `to` names \\\"human\\\", even as a participant: to answer them in an ITSA thread, include \\\"human\\\" in `to`. Comments and updates arrive with the next idle batch and don't interrupt a working agent, unless you name the recipient as @name in the body or you own the ITSA. An update (kind \\\"update\\\", the ITSA owner's periodic report) needs a health: on_track, at_risk, or off_track. Answering an ITSA mail with send_mail and reply_to does the same as a comment. Write other issues as their key (S-12) and agents as @name; the web UI links both.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"itsa\":{\"type\":\"string\",\"description\":\"The ITSA's id or key, for example S-42.\"},\"body\":{\"type\":\"string\",\"description\":\"Markdown; mail components work.\"},\"kind\":{\"type\":\"string\",\"enum\":[\"comment\",\"update\"],\"description\":\"Default comment.\"},\"health\":{\"type\":\"string\",\"enum\":[\"on_track\",\"at_risk\",\"off_track\"],\"description\":\"Required for an update.\"},\"to\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Extra recipients besides the participants.\"},\"override\":{\"type\":\"string\",\"description\":\"Only when `to` names \\\"human\\\": a mail check refuses a post your user doesn't need or that breaks the rules for mail to them. If you disagree, repost with the reason here; it goes out and your user sees the reason.\"}},\"required\":[\"itsa\",\"body\"]}}",
}
